const BASE = new URL('./assets/', import.meta.url).href;

class ZimmLogo extends HTMLElement {
  static get observedAttributes() {
    return ['variant'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const variant = this.getAttribute('variant');
    const src = variant === 'inverse'
      ? `${BASE}logo-light.svg`
      : `${BASE}logo-dark.svg`;

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; }
        img { display: block; width: 100%; height: auto; }
      </style>
      <img src="${src}" alt="Zimmermann" draggable="false">
    `;
  }
}

customElements.define('zimm-logo', ZimmLogo);

