import '../text-input/zimm-text-input.js';
import '../button/zimm-button.js';

class ZimmInputAction extends HTMLElement {
  static get observedAttributes() {
    return ['label', 'type', 'name', 'placeholder', 'icon', 'button-type', 'button-label', 'inverse', 'error-text'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const label       = this.getAttribute('label')        || '';
    const type        = this.getAttribute('type')         || 'text';
    const name        = this.getAttribute('name')         || '';
    const placeholder = this.getAttribute('placeholder')  || '';
    const icon        = this.getAttribute('icon')         || 'chevron-right';
    const buttonType  = this.getAttribute('button-type')  || 'submit';
    const buttonLabel = this.getAttribute('button-label') || 'Submit';
    const errorText   = this.getAttribute('error-text')   || '';
    const inv         = this.hasAttribute('inverse');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; width: 100%; }
      </style>
      <zimm-text-input
        label="${label}"
        type="${type}"
        ${name        ? `name="${name}"`               : ''}
        ${placeholder ? `placeholder="${placeholder}"` : ''}
        ${errorText   ? `error-text="${errorText}"`    : ''}
        ${inv         ? 'inverse'                      : ''}
      >
        <zimm-button
          slot="trailing"
          variant="icon"
          icon="${icon}"
          type="${buttonType}"
          label="${buttonLabel}"
          ${inv ? 'inverse' : ''}
        ></zimm-button>
      </zimm-text-input>
    `;
  }
}

customElements.define('zimm-input-action', ZimmInputAction);

