const ASSETS = new URL('./assets/', import.meta.url).href;

const COUNTRIES = {
  'us': 'United States',
  'au': 'Australia',
  'uk': 'United Kingdom',
  'eu': 'European Union',
  'ca': 'Canada',
  'cl': 'Chile',
  'ch': 'Switzerland',
  'nz': 'New Zealand',
  'br': 'Brazil',
};

class ZimmFlag extends HTMLElement {
  static get observedAttributes() {
    return ['country', 'aria-hidden'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const country  = this.getAttribute('country') || '';
    const isValid  = country in COUNTRIES;
    const isHidden = this.getAttribute('aria-hidden') === 'true';
    const label    = COUNTRIES[country] || country;

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; line-height: 0; }
        img {
          display: block;
          width: 100%;
          height: auto;
          border-radius: 1px;
