class ZimmSelect extends HTMLElement {
  static get observedAttributes() {
    return ['placeholder', 'options', 'value', 'name', 'disabled', 'inverse', 'error-text'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const placeholder = this.getAttribute('placeholder') || 'Select';
    const name        = this.getAttribute('name')        || '';
    const value       = this.getAttribute('value')       || '';
    const errorText   = this.getAttribute('error-text')  || '';
    const disabled    = this.hasAttribute('disabled');
    const iconBase    = new URL('../icon/assets/', import.meta.url).href;

    let options = [];
    try { options = JSON.parse(this.getAttribute('options') || '[]'); } catch (e) {}

    const hasValue = !!value;
    const hasError = !!errorText;

    const rowClass = ['input-row', disabled ? 'is-disabled' : '', hasError ? 'is-error' : ''].filter(Boolean).join(' ');
    const selClass = ['native-select', !hasValue ? 'is-placeholder' : ''].filter(Boolean).join(' ');

    const optionsHtml = options
      .map(o => `<option value="${o.value}"${value === o.value ? ' selected' : ''}>${o.label}</option>`)
      .join('');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; width: 100%; }
        * { box-sizing: border-box; }

        .field {
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-xs);
          width: 100%;
        }

        .input-row {
          display: flex;
          align-items: center;
          gap: var(--zimm-scale-xs);
          border-bottom: 1px solid var(--zimm-color-border-forms);
          padding: var(--zimm-scale-2xs) 0;
          min-height: 36px;
          transition:
            border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard),
            box-shadow   var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        .input-row:hover        { border-bottom-color: var(--zimm-color-text-default); }
        .input-row:focus-within {
          border-bottom-color: var(--zimm-color-text-default);
          box-shadow: 0 1px 0 0 var(--zimm-color-text-default);
        }
        .input-row.is-error                      { border-bottom-color: var(--zimm-color-status-error); }
        .input-row.is-error:hover,
        .input-row.is-error:focus-within         {
          border-bottom-color: var(--zimm-color-status-error);
          box-shadow: 0 1px 0 0 var(--zimm-color-status-error);
        }
        .input-row.is-disabled {
          border-bottom-color: color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent);
          pointer-events: none;
        }

        :host([inverse]) .input-row              { border-bottom-color: var(--zimm-color-grey-white); }
        :host([inverse]) .input-row:hover        { border-bottom-color: var(--zimm-color-grey-white); }
        :host([inverse]) .input-row:focus-within {
          border-bottom-color: var(--zimm-color-grey-white);
          box-shadow: 0 1px 0 0 var(--zimm-color-grey-white);
        }
        :host([inverse]) .input-row.is-error     { border-bottom-color: var(--zimm-color-status-error-bg); }
        :host([inverse]) .input-row.is-error:hover,
        :host([inverse]) .input-row.is-error:focus-within {
          border-bottom-color: var(--zimm-color-status-error-bg);
          box-shadow: 0 1px 0 0 var(--zimm-color-status-error-bg);
        }
        :host([inverse]) .input-row.is-disabled  { border-bottom-color: var(--zimm-color-grey-white); opacity: 0.5; }

        .native-select {
          flex: 1;
          background: transparent;
          border: none;
          outline: none;
          padding: 0;
          appearance: none;
          -webkit-appearance: none;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-default);
          cursor: pointer;
          min-height: 20px;
        }

        .native-select.is-placeholder { color: var(--zimm-color-text-secondary); }

        .native-select:disabled {
          color: color-mix(in srgb, var(--zimm-color-text-default) 50%, transparent);
          -webkit-text-fill-color: color-mix(in srgb, var(--zimm-color-text-default) 50%, transparent);
          cursor: default;
        }

        :host([inverse]) .native-select                { color: var(--zimm-color-grey-white); }
        :host([inverse]) .native-select.is-placeholder { color: var(--zimm-color-grey-300); }
        :host([inverse]) .native-select:disabled       {
          color: color-mix(in srgb, var(--zimm-color-grey-white) 50%, transparent);
          -webkit-text-fill-color: color-mix(in srgb, var(--zimm-color-grey-white) 50%, transparent);
        }

        .trail-icon {
          flex-shrink: 0;
          width: 20px;
          height: 20px;
          display: block;
          pointer-events: none;
        }
        :host([inverse]) .trail-icon { filter: invert(1); }

        .error-text {
          margin: 0;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-status-error);
        }
        :host([inverse]) .error-text { color: var(--zimm-color-status-error-bg); }
      </style>

      <div class="field">
        <div class="${rowClass}">
          <select
            id="native-select"
            class="${selClass}"
            ${name     ? `name="${name}"` : ''}
            ${disabled ? 'disabled'       : ''}
            ${hasError ? 'aria-invalid="true" aria-describedby="error-msg"' : ''}
          >
            <option value="" disabled${!hasValue ? ' selected' : ''} hidden>${placeholder}</option>
            ${optionsHtml}
          </select>
          <img class="trail-icon" src="${iconBase}chevron-down.svg" alt="" aria-hidden="true">
        </div>
        ${hasError ? `<p id="error-msg" class="error-text" role="alert">${errorText}</p>` : ''}
      </div>
    `;

    const sel = this.shadowRoot.querySelector('.native-select');
    if (sel) {
      sel.addEventListener('change', (e) => {
        sel.classList.toggle('is-placeholder', !e.target.value);
      });
    }
  }
}

customElements.define('zimm-select', ZimmSelect);

