class ZimmSearchOverlay extends HTMLElement {
  static get observedAttributes() {
    return ['open', 'placeholder'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._onKeyDown   = this._onKeyDown.bind(this);
    this._onSearchOpen = () => this.setAttribute('open', '');
  }

  connectedCallback() {
    this._render();
    document.addEventListener('keydown',          this._onKeyDown);
    document.addEventListener('zimm-search-open', this._onSearchOpen);
  }

  disconnectedCallback() {
    document.removeEventListener('keydown',          this._onKeyDown);
    document.removeEventListener('zimm-search-open', this._onSearchOpen);
  }

  attributeChangedCallback(name, oldVal, newVal) {
    if (oldVal === newVal) return;
    if (name === 'open') {
      if (this.hasAttribute('open')) {
        requestAnimationFrame(() => this.shadowRoot.querySelector('.search-input')?.focus());
      }
    } else {
      this._render();
    }
  }

  _close() {
    this.removeAttribute('open');
    this.dispatchEvent(new CustomEvent('zimm-search-close', { bubbles: true, composed: true }));
  }

  _submit() {
    const value = this.shadowRoot.querySelector('.search-input')?.value ?? '';
    this.dispatchEvent(new CustomEvent('zimm-search-submit', { bubbles: true, composed: true, detail: { value } }));
  }

  _onKeyDown(e) {
    if (e.key === 'Escape' && this.hasAttribute('open')) this._close();
  }

  _render() {
    const placeholder = this.getAttribute('placeholder') || 'Search';
    const iconBase    = new URL('../icon/assets/', import.meta.url).href;

    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: block;
          position: fixed;
          inset: 0;
          background: var(--zimm-color-bg-07);
          z-index: 200;
          opacity: 0;
          pointer-events: none;
          transition: opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        :host([open]) {
          opacity: 1;
          pointer-events: auto;
        }

        /* Close button: top-right, aligns with nav icons */
        .close-btn {
          position: absolute;
          top: var(--zimm-scale-1000);
          right: var(--zimm-scale-1000);
          background: none;
          border: none;
          padding: 0;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          width: 20px;
          height: 20px;
        }

        .close-btn:focus-visible {
          outline: 2px solid var(--zimm-color-border-focus);
          outline-offset: 2px;
          border-radius: 2px;
        }

        .close-btn img { width: 20px; height: 20px; display: block; }

        /* Search field: centered, ~15% from top */
        .search-wrap {
          display: flex;
          flex-direction: column;
          align-items: center;
          padding: 15vh var(--zimm-scale-1000) 0;
        }

        .search-area {
          display: flex;
          align-items: flex-end;
          gap: var(--zimm-scale-400);
          width: 100%;
          max-width: 480px;
        }

        .search-field {
          flex: 1;
          border-bottom: 1px solid var(--zimm-color-border-forms);
          padding-bottom: var(--zimm-scale-2xs);
          transition: border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        .search-field:focus-within { border-bottom-color: var(--zimm-color-text-default); }

        .search-input {
          width: 100%;
          background: transparent;
          border: none;
          outline: none;
          padding: 0;
          appearance: none;
          -webkit-appearance: none;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-default);
          min-height: 20px;
        }

        .search-input::-webkit-search-cancel-button,
        .search-input::-webkit-search-decoration { display: none; }

        .search-input::placeholder { color: var(--zimm-color-text-secondary); opacity: 1; }

        .ok-btn {
          flex-shrink: 0;
          background: var(--zimm-color-grey-500);
          color: var(--zimm-color-grey-white);
          border: none;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          padding: var(--zimm-scale-xs) var(--zimm-scale-400);
          cursor: pointer;
          white-space: nowrap;
          line-height: 20px;
        }

        .ok-btn:hover { background: var(--zimm-color-grey-900); }

        .ok-btn:focus-visible {
          outline: 2px solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }

        .placeholder-notice {
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          background: #f5a623;
          color: #000;
          font-family: monospace;
          font-size: 11px;
          font-weight: bold;
          text-align: center;
          padding: 4px 8px;
          letter-spacing: 0.05em;
          pointer-events: none;
        }
      </style>

      <div class="placeholder-notice" aria-hidden="true">PLACEHOLDER: functionality only, visual design pending</div>

      <button class="close-btn" type="button" aria-label="Close search">
        <img src="${iconBase}close.svg" alt="" aria-hidden="true">
      </button>

      <div class="search-wrap">
        <div class="search-area">
          <div class="search-field">
            <input
              class="search-input"
              type="search"
              placeholder="${placeholder}"
              aria-label="${placeholder}"
            >
          </div>
          <button class="ok-btn" type="button">OK</button>
        </div>
      </div>
    `;

    this.shadowRoot.querySelector('.close-btn').addEventListener('click', () => this._close());
    this.shadowRoot.querySelector('.ok-btn').addEventListener('click',    () => this._submit());
    this.shadowRoot.querySelector('.search-input').addEventListener('keydown', (e) => {
      if (e.key === 'Enter') this._submit();
    });

    if (this.hasAttribute('open')) {
      requestAnimationFrame(() => this.shadowRoot.querySelector('.search-input')?.focus());
    }
  }
}

customElements.define('zimm-search-overlay', ZimmSearchOverlay);

