class ZimmBanner extends HTMLElement {
  static get observedAttributes() {
    return ['message', 'theme'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _dismiss() {
    this.style.display = 'none';
    this.dispatchEvent(new CustomEvent('zimm-banner-dismiss', { bubbles: true }));
  }

  _render() {
    const message = this.getAttribute('message') || '';
    const theme   = this.getAttribute('theme') || 'default';

    const bg   = theme === 'dark' ? 'var(--zimm-color-bg-05)'
               : theme === 'warm' ? 'var(--zimm-color-bg-04)'
               :                    'var(--zimm-color-bg-02)';

    const text = theme === 'dark' ? 'var(--zimm-color-text-inverse)'
               :                    'var(--zimm-color-text-default)';

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; width: 100%; }

        .banner {
          display: flex;
          align-items: center;
          justify-content: space-between;
          box-sizing: border-box;
          width: 100%;
          padding: 10px 30px;
          background: ${bg};
        }

        .message {
          flex: 1;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: var(--zimm-font-lineheight-2xs);
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: ${text};
          text-align: left;
        }

        .dismiss {
          flex-shrink: 0;
          background: none;
          border: none;
          padding: 0;
          margin-left: var(--zimm-scale-400);
          cursor: pointer;
          display: flex;
          align-items: center;
          color: ${text};
        }

        .dismiss:focus-visible {
          outline: var(--zimm-border-width-default) solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }

        @media (min-width: 768px) {
          .banner {
            height: 40px;
            padding: 0 40px;
          }
          .message { text-align: center; }
        }
      </style>
      <div class="banner" role="status" aria-live="polite" aria-atomic="true">
        <span class="message">${message}</span>
        <button class="dismiss" type="button" aria-label="Dismiss banner">
          <zimm-icon type="close" size="20" aria-hidden="true"></zimm-icon>
        </button>
      </div>
    `;

    this.shadowRoot.querySelector('.dismiss').addEventListener('click', () => this._dismiss());
  }
}

customElements.define('zimm-banner', ZimmBanner);

