class ZimmDisclaimer extends HTMLElement {
  static get observedAttributes() {
    return ['disclaimer-text', 'read-more-href'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const text = this.getAttribute('disclaimer-text') || '';
    const href = this.getAttribute('read-more-href') || '';

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        * { box-sizing: border-box; }

        .disclaimer {
          background: var(--zimm-color-bg-02);
          padding: var(--zimm-scale-1000) var(--zimm-scale-800);
        }

        .container {
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-400);
          width: 100%;
        }

        .label {
          margin: 0;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: var(--zimm-font-lineheight-2xs);
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
          opacity: 0.8;
        }

        .body {
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-400);
        }

        .body-text {
          margin: 0;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: var(--zimm-font-lineheight-2xs);
          color: var(--zimm-color-text-secondary);
        }

        .read-more {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-3xs);
          letter-spacing: -0.14px;
          text-transform: uppercase;
          text-decoration: underline;
          text-underline-offset: 2px;
          color: var(--zimm-color-text-default);
        }

        .read-more:hover { color: var(--zimm-color-text-secondary); }

        /* ---- Tablet: 768px+ ---- */
        @media (min-width: 768px) {
          .disclaimer {
            padding: var(--zimm-scale-800) var(--zimm-scale-1000);
          }

          .container {
            display: grid;
            grid-template-columns: 320px 1fr;
            gap: 0 var(--zimm-scale-4xl);
            align-items: start;
          }
        }

        /* ---- Desktop: 1024px+ ---- */
        @media (min-width: 1024px) {
          .container {
            grid-template-columns: 1fr 600px;
          }
        }
      </style>

      <div class="disclaimer" role="note">
        <div class="container">
          <p class="label">Terms and Conditions</p>
