class ZimmCardBaseline extends HTMLElement {
  static get observedAttributes() {
    return ['cta-label', 'cta-href', 'no-click', 'no-cta'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this._render();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    this._render();
  }

  _render() {
    const ctaLabel = this.getAttribute('cta-label') || 'Call to Action';
    const ctaHref  = this.getAttribute('cta-href')  || '#';
    const hideCta  = this.hasAttribute('no-cta');

    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: flex;
          flex-direction: column;
          align-items: center;
          position: relative;
        }

        .image-wrap {
          width: 100%;
          height: var(--card-image-height, auto);
          aspect-ratio: var(--card-image-aspect-ratio, auto);
          overflow: hidden;
          background: var(--zimm-color-bg-01);
          flex-shrink: 0;
        }

        ::slotted(img),
        ::slotted(picture) {
          display: block;
          width: 100%;
          height: 100%;
          object-fit: cover;
        }

        .text {
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-m);
          width: 100%;
          box-sizing: border-box;
          color: var(--zimm-color-text-default);
          padding: var(--zimm-scale-2xl) var(--zimm-scale-3xl) var(--zimm-scale-l) var(--zimm-scale-3xl);
        }

        /* display:contents makes empty slots collapse out of the flex flow. Inherited font/text props cascade to slotted content. */
        ::slotted(*) { margin: 0; }

        slot[name="collection-name-l"] {
          display: contents;
          font-family: var(--zimm-font-family-heading);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-md);
          line-height: var(--zimm-font-lineheight-md);
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
        }

        slot[name="collection-name-s"] {
          display: contents;
          font-family: var(--zimm-font-family-heading);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-xs);
          line-height: var(--zimm-font-lineheight-2xs);
          letter-spacing: var(--zimm-font-letterspacing-xs);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
        }

        slot[name="product-name"] {
          display: contents;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-3xs);
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
        }

        slot[name="price"] {
          display: contents;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-2xs);
          letter-spacing: var(--zimm-font-letterspacing-sm);
          color: var(--zimm-color-text-default);
        }

        /* Stretch link: covers the full card. Always present unless no-click. Separate from the visible CTA. */
        .stretch-link {
          position: absolute;
          inset: 0;
        }

        :host([no-click]) .stretch-link {
          display: none;
        }

        .cta {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-3xs);
          letter-spacing: var(--zimm-font-letterspacing-xs);
          text-transform: uppercase;
          text-decoration: underline;
          text-decoration-color: currentColor;
          color: var(--zimm-color-link-default);
          transition: color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
          position: relative;
          z-index: 1;
        }

        .cta:hover {
          color: var(--zimm-color-link-hover);
        }

        .cta:focus-visible {
          outline: var(--zimm-border-width-default) solid var(--zimm-color-border-focus);
          outline-offset: 2px;
          color: var(--zimm-color-link-hover);
        }

        /* Hover: add card-level hover effects here (e.g. image scale, overlay, text colour shift). */
        :host(:hover) {

        }

        /* Mobile */
        @media (max-width: 767px) {
          .text {
            padding: var(--zimm-scale-2xl) var(--zimm-scale-2xl) var(--zimm-scale-l) var(--zimm-scale-2xl);
          }
        }
      </style>

      <a class="stretch-link" href="${ctaHref}" aria-hidden="true" tabindex="-1"></a>
      <div class="image-wrap">
        <slot name="image"></slot>
      </div>
      <div class="text">
        <slot name="collection-name-l"></slot>
        <slot name="collection-name-s"></slot>
        <slot name="product-name"></slot>
        <slot name="price"></slot>
        ${!hideCta ? `<a class="cta" href="${ctaHref}">${ctaLabel}</a>` : ''}
      </div>
    `;
  }
}

customElements.define('zimm-card-baseline', ZimmCardBaseline);

