class ZimmCardEditorial extends HTMLElement {
  static get observedAttributes() {
    return ['text-align'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this._render();
    this._bindTitleSlot();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    this._render();
  }

  _bindTitleSlot() {
    const slot = this.shadowRoot.querySelector('slot[name="title"]');
    if (!slot) return;
    const toggle = () => {
      const hasContent = slot.assignedNodes({ flatten: true }).length > 0;
      this.shadowRoot.querySelector('.card-title').style.display = hasContent ? '' : 'none';
    };
    slot.addEventListener('slotchange', toggle);
    toggle();
  }

  _render() {
    const textAlign = this.getAttribute('text-align') || 'left';

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; height: 100%; }

        article {
          display: flex;
          flex-direction: column;
          height: 100%;
          text-align: ${textAlign};
        }

        .card-title {
          font-family: var(--zimm-font-family-heading);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-xs);
          line-height: var(--zimm-font-lineheight-2xs);
          letter-spacing: var(--zimm-font-letterspacing-xs);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
          padding: 0 var(--zimm-scale-3xl) var(--zimm-scale-3xl) var(--zimm-scale-3xl);
          margin: 0;
          box-sizing: border-box;
        }

        .img-wrap {
          display: block;
          width: 100%;
          overflow: hidden;
          flex: 1;
          min-height: 0;
        }

        ::slotted(img) {
          width: 100%;
          height: 100%;
          object-fit: cover;
          display: block;
        }

        .card-body {
          padding: var(--zimm-scale-3xl) 0 0 var(--zimm-scale-3xl);
          box-sizing: border-box;
        }

        :host([text-align="center"]) .card-body {
          padding-right: var(--zimm-scale-3xl);
        }

        .card-desc {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-xs);
          line-height: var(--zimm-font-lineheight-xs);
          letter-spacing: var(--zimm-font-letterspacing-xs);
          color: var(--zimm-color-text-default);
          margin: 0;
        }

        .card-link {
          display: block;
          margin-top: var(--zimm-scale-l);
        }

        ::slotted(a) {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-2xs);
          line-height: var(--zimm-font-lineheight-3xs);
          letter-spacing: var(--zimm-font-letterspacing-xs);
          text-transform: uppercase;
          text-decoration: underline;
          text-decoration-color: currentColor;
          color: var(--zimm-color-text-default);
          transition: color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        ::slotted(a:hover) {
          color: var(--zimm-color-link-hover);
        }

        @media (max-width: 767px) {
          .card-title {
            padding-left: var(--zimm-grid-margin-mobile);
            padding-right: var(--zimm-grid-margin-mobile);
          }
          .card-body {
            padding-left: var(--zimm-grid-margin-mobile);
          }
          .card-desc {
            font-size: var(--zimm-font-size-2xs);
            line-height: var(--zimm-font-lineheight-2xs);
            letter-spacing: var(--zimm-font-letterspacing-sm);
          }
        }
      </style>
      <article>
        <div class="card-title"><slot name="title"></slot></div>
        <span class="img-wrap"><slot name="image"></slot></span>
        <div class="card-body">
          <div class="card-desc"><slot name="description"></slot></div>
          <div class="card-link"><slot name="link"></slot></div>
        </div>
      </article>
    `;
  }
}

customElements.define('zimm-card-editorial', ZimmCardEditorial);

