1	const _NAV_LABELS = ['New', 'Clothing', 'Accessories', 'Collections', 'Z.Immerse'];
2	
3	class ZimmNavigation extends HTMLElement {
4	  static get observedAttributes() {
5	    return ['active'];
6	  }
7	
8	  constructor() {
9	    super();
10	    this.attachShadow({ mode: 'open' });
11	    this._handleClick    = this._handleClick.bind(this);
12	    this._activeIndex    = -1;
13	    this._mobileView     = null; // null | 'home' | 0-4
14	    this._prevMobileView = null;
15	  }
16	
17	  connectedCallback() {
18	    this._render();
19	    this.shadowRoot.addEventListener('click', this._handleClick);
20	    if (this.hasAttribute('active')) {
21	      this._updateActiveState();
22	    }
23	  }
24	
25	  disconnectedCallback() {
26	    this.shadowRoot.removeEventListener('click', this._handleClick);
27	  }
28	
29	  attributeChangedCallback(name, oldValue, newValue) {
30	    if (oldValue === newValue) return;
31	    this._updateActiveState();
32	  }
33	
34	  _isMobile() {
35	    return window.matchMedia('(max-width: 767px)').matches;
36	  }
37	
38	  _mobileCloseTransition() {
39	    if (!this._isMobile()) return;
40	    this.classList.add('mobile-closing');
41	    setTimeout(() => this.classList.remove('mobile-closing'), 300);
42	  }
43	
44	  _handleClick(e) {
45	    const inMobileClose  = e.target.closest('.mobile-close-btn');
46	    const inMobileBack   = e.target.closest('.mobile-back-btn');
47	    const inMobileNavBtn = e.target.closest('.mobile-nav-btn');
48	    const inHamburger    = e.target.closest('.hamburger-btn');
49	    const inNavLinks     = e.target.closest('.nav-links');
50	    const inClose        = e.target.closest('.right-active');
51	
52	    if (inMobileClose) {
53	      this._mobileCloseTransition();
54	      this._activeIndex    = -1;
55	      this._mobileView     = null;
56	      this._prevMobileView = null;
57	      this.removeAttribute('active');
58	      this._syncMobileView();
59	      this._updateActiveState();
60	
61	    } else if (inMobileBack) {
62	      this._mobileView = 'home';
63	      this._syncMobileView();
64	
65	    } else if (inMobileNavBtn) {
66	      this._mobileView = parseInt(inMobileNavBtn.dataset.index);
67	      this._syncMobileView();
68	
69	    } else if (inHamburger) {
70	      this.toggleAttribute('active');
71	      if (this.hasAttribute('active')) {
72	        if (this._isMobile()) {
73	          this._mobileView = 'home';
74	          this._syncMobileView();
75	        }
76	      } else {
77	        this._mobileCloseTransition();
78	        this._activeIndex    = -1;
79	        this._mobileView     = null;
80	        this._prevMobileView = null;
81	        this._syncNavItems();
82	        this._syncPanelSection();
83	        this._syncMobileView();
84	      }
85	      this._updateActiveState();
86	
87	    } else if (inNavLinks) {
88	      const navItem = e.target.closest('zimm-nav-item');
89	      if (!navItem) return;
90	      const items = [...this.shadowRoot.querySelectorAll('.nav-links zimm-nav-item')];
91	      const idx   = items.indexOf(navItem);
92	      if (idx === this._activeIndex) {
93	        this._activeIndex = -1;
94	        this.removeAttribute('active');
95	      } else {
96	        this._activeIndex = idx;
97	        this.setAttribute('active', '');
98	      }
99	      this._syncNavItems(items);
100	      this._syncPanelSection();
101	      this._updateActiveState();
102	
103	    } else if (e.target.closest('.search-trigger')) {
104	      this.dispatchEvent(new CustomEvent('zimm-search-open', { bubbles: true, composed: true }));
105	
106	    } else if (inClose) {
107	      this._activeIndex = -1;
108	      this.removeAttribute('active');
109	      this._syncNavItems();
110	      this._syncPanelSection();
111	      this._updateActiveState();
112	    }
113	  }
114	
115	  _syncNavItems(items) {
116	    const navItems = items || [...this.shadowRoot.querySelectorAll('.nav-links zimm-nav-item')];
117	    navItems.forEach((item, i) => {
118	      if (i === this._activeIndex) item.setAttribute('active', '');
119	      else item.removeAttribute('active');
120	    });
121	  }
122	
123	  _syncPanelSection() {
124	    const sections  = [...this.shadowRoot.querySelectorAll('.panel-section')];
125	    const isClosing = this._activeIndex === -1;
126	
127	    sections.forEach((s, i) => {
128	      const isActive  = i === this._activeIndex;
129	      const wasActive = s.classList.contains('is-active');
130	      const menus     = s.querySelector('slot')?.assignedElements() ?? [];
131	
132	      if (isActive) {
133	        s.classList.add('is-active');
134	        menus.forEach(m => {
135	          m.removeAttribute('closing');
136	          requestAnimationFrame(() => m.setAttribute('open', ''));
137	        });
138	      } else if (wasActive && isClosing) {
139	        menus.forEach(m => {
140	          m.removeAttribute('open');
141	          m.setAttribute('closing', '');
142	        });
143	        setTimeout(() => {
144	          s.classList.remove('is-active');
145	          menus.forEach(m => m.removeAttribute('closing'));
146	        }, 300);
147	      } else {
148	        s.classList.remove('is-active');
149	        menus.forEach(m => {
150	          m.removeAttribute('open');
151	          m.removeAttribute('closing');
152	        });
153	      }
154	    });
155	  }
156	
157	  _syncMobileView() {
158	    const root       = this.shadowRoot;
159	    const panel      = root.querySelector('.menu-panel');
160	    const homeEl     = root.querySelector('.mobile-home');
161	    const subContent = root.querySelector('.mobile-sub-content');
162	    const sections   = [...root.querySelectorAll('.panel-section')];
163	
164	    if (!panel) return;
165	
166	    const prev = this._prevMobileView;
167	    this._prevMobileView = this._mobileView;
168	
169	    if (!this._isMobile() || this._mobileView === null) {
170	      panel.classList.remove('is-mobile-sub');
171	      if (homeEl)     homeEl.style.cssText     = '';
172	      if (subContent) subContent.style.cssText = '';
173	      sections.forEach(s => {
174	        s.classList.remove('is-active');
175	        (s.querySelector('slot')?.assignedElements() ?? []).forEach(m => {
176	          m.removeAttribute('mobile');
177	          m.removeAttribute('open');
178	          m.removeAttribute('closing');
179	        });
180	      });
181	      return;
182	    }
183	
184	    if (this._mobileView === 'home') {
185	      sections.forEach(s => {
186	        s.classList.remove('is-active');
187	        (s.querySelector('slot')?.assignedElements() ?? []).forEach(m => {
188	          m.removeAttribute('mobile');
189	          m.removeAttribute('open');
190	          m.removeAttribute('closing');
191	        });
192	      });
193	
194	      if (prev !== null && prev !== 'home') {
195	        this._animateTransition(homeEl, subContent, panel, 'back');
196	      } else {
197	        panel.classList.remove('is-mobile-sub');
198	        homeEl.style.display     = 'flex';
199	        subContent.style.display = 'none';
200	        homeEl.style.animation   = '';
201	      }
202	
203	    } else {
204	      const idx = this._mobileView;
205	      sections.forEach((s, i) => {
206	        const menus = s.querySelector('slot')?.assignedElements() ?? [];
207	        if (i === idx) {
208	          s.classList.add('is-active');
209	          menus.forEach(m => {
210	            m.removeAttribute('open');
211	            m.removeAttribute('closing');
212	            m.setAttribute('mobile', '');
213	          });
214	        } else {
215	          s.classList.remove('is-active');
216	          menus.forEach(m => {
217	            m.removeAttribute('mobile');
218	            m.removeAttribute('open');
