const _NAV_LABELS = ['New', 'Clothing', 'Accessories', 'Collections', 'Z.Immerse'];

class ZimmNavigation extends HTMLElement {
  static get observedAttributes() {
    return ['active'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._handleClick    = this._handleClick.bind(this);
    this._activeIndex    = -1;
    this._mobileView     = null; // null | 'home' | 0-4
    this._prevMobileView = null;
  }

  connectedCallback() {
    this._render();
    this.shadowRoot.addEventListener('click', this._handleClick);
    if (this.hasAttribute('active')) {
      this._updateActiveState();
    }
  }

  disconnectedCallback() {
    this.shadowRoot.removeEventListener('click', this._handleClick);
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    this._updateActiveState();
  }

  _isMobile() {
    return window.matchMedia('(max-width: 767px)').matches;
  }

  _mobileCloseTransition() {
    if (!this._isMobile()) return;
    this.classList.add('mobile-closing');
    setTimeout(() => this.classList.remove('mobile-closing'), 300);
  }

  _handleClick(e) {
    const inMobileClose  = e.target.closest('.mobile-close-btn');
    const inMobileBack   = e.target.closest('.mobile-back-btn');
    const inMobileNavBtn = e.target.closest('.mobile-nav-btn');
    const inHamburger    = e.target.closest('.hamburger-btn');
    const inNavLinks     = e.target.closest('.nav-links');
    const inClose        = e.target.closest('.right-active');

    if (inMobileClose) {
      this._mobileCloseTransition();
      this._activeIndex    = -1;
      this._mobileView     = null;
      this._prevMobileView = null;
      this.removeAttribute('active');
      this._syncMobileView();
      this._updateActiveState();

    } else if (inMobileBack) {
      this._mobileView = 'home';
      this._syncMobileView();

    } else if (inMobileNavBtn) {
      this._mobileView = parseInt(inMobileNavBtn.dataset.index);
      this._syncMobileView();

    } else if (inHamburger) {
      this.toggleAttribute('active');
      if (this.hasAttribute('active')) {
        if (this._isMobile()) {
          this._mobileView = 'home';
          this._syncMobileView();
        }
      } else {
        this._mobileCloseTransition();
        this._activeIndex    = -1;
        this._mobileView     = null;
        this._prevMobileView = null;
        this._syncNavItems();
        this._syncPanelSection();
        this._syncMobileView();
      }
      this._updateActiveState();

    } else if (inNavLinks) {
      const navItem = e.target.closest('zimm-nav-item');
      if (!navItem) return;
      const items = [...this.shadowRoot.querySelectorAll('.nav-links zimm-nav-item')];
      const idx   = items.indexOf(navItem);
      if (idx === this._activeIndex) {
        this._activeIndex = -1;
        this.removeAttribute('active');
      } else {
        this._activeIndex = idx;
        this.setAttribute('active', '');
      }
      this._syncNavItems(items);
      this._syncPanelSection();
      this._updateActiveState();

    } else if (e.target.closest('.search-trigger')) {
      this.dispatchEvent(new CustomEvent('zimm-search-open', { bubbles: true, composed: true }));

    } else if (inClose) {
      this._activeIndex = -1;
      this.removeAttribute('active');
      this._syncNavItems();
      this._syncPanelSection();
      this._updateActiveState();
    }
  }

  _syncNavItems(items) {
    const navItems = items || [...this.shadowRoot.querySelectorAll('.nav-links zimm-nav-item')];
    navItems.forEach((item, i) => {
      if (i === this._activeIndex) item.setAttribute('active', '');
      else item.removeAttribute('active');
    });
  }

  _syncPanelSection() {
    const sections  = [...this.shadowRoot.querySelectorAll('.panel-section')];
    const isClosing = this._activeIndex === -1;

    sections.forEach((s, i) => {
      const isActive  = i === this._activeIndex;
      const wasActive = s.classList.contains('is-active');
      const menus     = s.querySelector('slot')?.assignedElements() ?? [];

      if (isActive) {
        s.classList.add('is-active');
        menus.forEach(m => {
          m.removeAttribute('closing');
          requestAnimationFrame(() => m.setAttribute('open', ''));
        });
      } else if (wasActive && isClosing) {
        menus.forEach(m => {
          m.removeAttribute('open');
          m.setAttribute('closing', '');
        });
        setTimeout(() => {
          s.classList.remove('is-active');
          menus.forEach(m => m.removeAttribute('closing'));
        }, 300);
      } else {
        s.classList.remove('is-active');
        menus.forEach(m => {
          m.removeAttribute('open');
          m.removeAttribute('closing');
        });
      }
    });
  }

  _syncMobileView() {
    const root       = this.shadowRoot;
    const panel      = root.querySelector('.menu-panel');
    const homeEl     = root.querySelector('.mobile-home');
    const subContent = root.querySelector('.mobile-sub-content');
    const sections   = [...root.querySelectorAll('.panel-section')];

    if (!panel) return;

    const prev = this._prevMobileView;
    this._prevMobileView = this._mobileView;

    if (!this._isMobile() || this._mobileView === null) {
      panel.classList.remove('is-mobile-sub');
      if (homeEl)     homeEl.style.cssText     = '';
      if (subContent) subContent.style.cssText = '';
      sections.forEach(s => {
        s.classList.remove('is-active');
        (s.querySelector('slot')?.assignedElements() ?? []).forEach(m => {
          m.removeAttribute('mobile');
          m.removeAttribute('open');
          m.removeAttribute('closing');
        });
      });
      return;
    }

    if (this._mobileView === 'home') {
      sections.forEach(s => {
        s.classList.remove('is-active');
        (s.querySelector('slot')?.assignedElements() ?? []).forEach(m => {
          m.removeAttribute('mobile');
          m.removeAttribute('open');
          m.removeAttribute('closing');
        });
      });

      if (prev !== null && prev !== 'home') {
        this._animateTransition(homeEl, subContent, panel, 'back');
      } else {
        panel.classList.remove('is-mobile-sub');
        homeEl.style.display     = 'flex';
        subContent.style.display = 'none';
        homeEl.style.animation   = '';
      }

    } else {
      const idx = this._mobileView;
      sections.forEach((s, i) => {
        const menus = s.querySelector('slot')?.assignedElements() ?? [];
        if (i === idx) {
          s.classList.add('is-active');
          menus.forEach(m => {
            m.removeAttribute('open');
            m.removeAttribute('closing');
            m.setAttribute('mobile', '');
          });
        } else {
          s.classList.remove('is-active');
          menus.forEach(m => {
            m.removeAttribute('mobile');
            m.removeAttribute('open');
            m.removeAttribute('closing');
          });
        }
      });

      if (prev === 'home' || prev === null) {
        this._animateTransition(homeEl, subContent, panel, 'forward');
      } else {
        panel.classList.add('is-mobile-sub');
        subContent.style.display = 'flex';
      }
    }
  }

  _animateTransition(homeEl, subContent, panel, direction) {
    const dur = '300ms var(--zimm-motion-easing-slides)';

    homeEl.style.animation     = '';
    subContent.style.animation = '';

    if (direction === 'forward') {
      // Button crossfade: X fades out, chevron fades in
      panel.classList.add('is-mobile-sub');
      homeEl.style.display       = 'flex';
      subContent.style.display   = 'flex';
      homeEl.style.animation     = `m-slide-out-left ${dur} both`;
      subContent.style.animation = `m-slide-in-right ${dur} both`;

      homeEl.addEventListener('animationend', () => {
        homeEl.style.display       = 'none';
        homeEl.style.animation     = '';
        subContent.style.animation = '';
      }, { once: true });

    } else {
      // Button crossfade: chevron fades out, X fades in (immediate, before slide completes)
      panel.classList.remove('is-mobile-sub');
      homeEl.style.display       = 'flex';
      homeEl.style.animation     = `m-slide-in-left ${dur} both`;
      subContent.style.animation = `m-slide-out-right ${dur} both`;

      subContent.addEventListener('animationend', () => {
        subContent.style.display   = 'none';
        homeEl.style.animation     = '';
        subContent.style.animation = '';
      }, { once: true });
    }
  }

  _updateActiveState() {
    const active = this.hasAttribute('active');
    const root   = this.shadowRoot;
    if (!root.querySelector('nav')) return;

    const btn = root.querySelector('.hamburger-btn');
    if (btn) {
      btn.setAttribute('aria-expanded', String(active));
      btn.setAttribute('aria-label', active ? 'Close menu' : 'Open menu');
    }

    const panel = root.querySelector('.menu-panel');
    if (panel) {
      panel.setAttribute('aria-hidden', String(!active));
    }
  }

  _render() {
    this.shadowRoot.innerHTML = `
      <style>
