          box-sizing: border-box;
          width: 100%;
          padding: var(--zimm-scale-600) var(--zimm-scale-800);
        }

        /* ---- Visibility defaults: mobile ---- */
        .hamburger-btn { display: flex; }
        .nav-links     { display: none; }
        .right-active  { display: none; }
        .right-desktop { display: none; }
        .right-tablet  { display: none; }
        .right-mobile  { display: flex; }

        /* Mobile hamburger icon states */
        .icon-close-mobile { display: none; }
        :host([active]) .icon-menu         { display: none; }
        :host([active]) .icon-close-mobile { display: flex; }

        /* ---- Tablet: 768px+ ---- */
        @media (min-width: 768px) {
          nav {
            align-items: center;
            padding: var(--zimm-scale-4xl) var(--zimm-scale-1000);
          }
          .hamburger-btn { display: none; }
          .nav-links     { display: flex; gap: var(--zimm-scale-1000); align-items: center; }
          .right-mobile  { display: none; }
          .right-tablet  { display: flex; align-items: center; }
        }

        /* ---- Desktop: 1024px+ ---- */
        @media (min-width: 1024px) {
          .right-tablet  { display: none; }
          .right-desktop { display: flex; align-items: center; gap: var(--zimm-scale-500); }
        }

        /* ---- Active overrides: tablet+ ---- */
        @media (min-width: 768px) {
          :host([active]) .right-tablet { display: none; }
          :host([active]) .right-active { display: flex; align-items: center; gap: var(--zimm-scale-200); }
          :host([active]) .right-active zimm-icon { margin-bottom: 4.5px; }
        }

        @media (min-width: 1024px) {
          :host([active]) .right-desktop { display: none; }
          :host([active]) .right-active  { display: flex; }
        }

        /* ---- Shared ---- */
        .icon-group {
          display: flex;
          gap: var(--zimm-scale-300);
          align-items: center;
        }

        .search-trigger { cursor: pointer; }

        .search-trigger-field {
          display: flex;
          align-items: center;
          align-self: stretch;
          border-bottom: 1px solid var(--zimm-color-border-forms);
          cursor: pointer;
          width: 180px;
        }

        .search-trigger-label {
          flex: 1;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
