          font-size: var(--zimm-font-size-3xs);
          letter-spacing: var(--zimm-font-letterspacing-footer);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
          text-decoration: none;
        }
      </style>

      <header role="banner">
        <nav aria-label="Main navigation">

          <button class="hamburger-btn"
