class ZimmMegaMenu extends HTMLElement {
  static get observedAttributes() {
    return ['layout', 'personal-label', 'mobile'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback()  { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const layout        = this.getAttribute('layout') || 'single';
    const rawLabel      = this.getAttribute('personal-label') || '';
    const personalLabel = rawLabel.replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const isDouble      = layout === 'double';

    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: flex;
          width: 100%;
          height: 100%;
          background: var(--zimm-color-bg-07);
          box-sizing: border-box;
          overflow: hidden;
        }

        /* ---- Left panel ---- */
        .left {
          flex: 0 0 40%;
          display: flex;
          flex-direction: column;
          padding: 60px var(--zimm-scale-1000) var(--zimm-scale-1000);
          box-sizing: border-box;
          min-width: 0;
          opacity: 0;
          transform: translateY(-24px);
        }

        /* ---- Token candidate: 60px not in scale. Confirm --zimm-scale-1500 or equivalent. ---- */

        .links-area {
          display: flex;
          gap: var(--zimm-scale-1000);
        }

        .links-col {
          flex: 1;
          display: flex;
          flex-direction: column;
          gap: 16px;
        }

        /* Heading wrapper for double-layout columns */
        .col-heading {
          display: block;
          margin-bottom: 24px;
        }

        .all-wrap {
          display: flex;
          flex-direction: column;
          gap: 16px;
          margin-top: var(--zimm-scale-1000);
        }

        .personal-wrap {
          margin-top: auto;
        }

        .personal-label {
          font-family: var(--zimm-font-family-serif);
          font-style: italic;
          font-weight: var(--zimm-font-weight-regular);
          font-size: var(--zimm-font-size-3xs);
          letter-spacing: 0;
          color: var(--zimm-color-text-muted);
          display: block;
          margin-bottom: var(--zimm-scale-300);
        }

        /* ---- Right panel ---- */
        .right {
          flex: 0 0 60%;
          max-width: 860px;
          margin-left: auto;
          position: relative;
          overflow: hidden;
          padding-top: 60px;
          box-sizing: border-box;
          background: var(--zimm-color-bg-07);
          opacity: 0;
        }

        /* ---- Slotted link styles ---- */
        ::slotted(a) {
          display: block;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: var(--zimm-font-lineheight-3xs);
          letter-spacing: var(--zimm-font-letterspacing-footer);
          text-transform: uppercase;
          color: var(--zimm-color-text-default);
          text-decoration: none;
          cursor: pointer;
        }

        /* ---- Image fill ---- */
        ::slotted(img) {
          width: 100%;
          height: 100%;
          object-fit: cover;
          display: block;
        }

        /* ---- Mobile layout ---- */
        /* height is provided by ::slotted([mobile]) { flex: 1 } in the navigation shadow DOM */
        :host([mobile]) {
          flex-direction: column;
          min-height: 0;
          overflow: hidden;
        }

        /* Personal swatch hidden on mobile */
        :host([mobile]) .personal-wrap {
          display: none;
        }

        /* Links panel: scrollable, fills remaining height above image */
        :host([mobile]) .left {
          flex: 1 1 auto;
          min-height: 0;
          overflow-y: auto;
          width: 100%;
          padding: var(--zimm-scale-800);
          opacity: 1;
          transform: none;
          animation: none !important;
        }

        /* Image panel: fixed height, always visible at bottom */
        :host([mobile]) .right {
          flex: 0 0 240px;
          width: 100%;
          max-width: none;
          margin-left: 0;
          padding-top: 0;
          opacity: 1;
          animation: none !important;
        }

        /* Stack double-layout columns on mobile */
        :host([mobile]) .links-area {
          flex-direction: column;
          gap: var(--zimm-scale-800);
        }

        /* ---- Open/close animations ---- */
        @keyframes left-enter {
          from { opacity: 0; transform: translateY(-24px); }
          to   { opacity: 1; transform: translateY(0); }
        }
        @keyframes right-enter {
          from { opacity: 0; }
          to   { opacity: 1; }
        }
        @keyframes fade-out {
          from { opacity: 1; }
          to   { opacity: 0; }
        }

        :host([open]) .left {
          animation: left-enter 300ms var(--zimm-motion-easing-fades) both;
        }
        :host([open]) .right {
          animation: right-enter 300ms var(--zimm-motion-easing-fades) both;
        }

        :host([closing]) .left {
          transform: translateY(0);
          animation: fade-out 300ms var(--zimm-motion-easing-fades) both;
        }
        :host([closing]) .right {
          animation: fade-out 300ms var(--zimm-motion-easing-fades) both;
        }
      </style>

      <div class="left">
        <div class="links-area">
          ${isDouble ? `
            <div class="links-col">
              <div class="col-heading"><slot name="links-heading"></slot></div>
              <slot name="links"></slot>
            </div>
            <div class="links-col">
              <div class="col-heading"><slot name="links-2-heading"></slot></div>
              <slot name="links-2"></slot>
            </div>
          ` : `
            <div class="links-col">
              <slot name="links"></slot>
            </div>
          `}
        </div>
        <div class="all-wrap">
          <slot name="all-link"></slot>
        </div>
        ${personalLabel ? `
          <div class="personal-wrap">
            <span class="personal-label">${personalLabel}</span>
            <slot name="personal"></slot>
          </div>
        ` : ''}
      </div>

      <div class="right">
        <slot name="image"></slot>
      </div>
    `;
  }
}

customElements.define('zimm-mega-menu', ZimmMegaMenu);

