        .link-group:nth-child(2) { grid-column: 1; }
        .link-group:nth-child(3) { grid-column: 2; grid-row: 1 / span 2; }

        .group-label {
          margin: 0 0 var(--zimm-scale-600);
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse-grey);
        }

        ul {
          list-style: none;
          padding: 0;
          margin: 0;
          display: flex;
          flex-direction: column;
          gap: var(--zimm-scale-400);
        }

        ul a {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-3xs);
          line-height: normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse);
          text-decoration: none;
        }

        ul a:hover { color: var(--zimm-color-text-inverse-grey); }

        /* ---- Contact icon row ---- */
        .icon-row {
          display: flex;
          gap: var(--zimm-scale-400);
          align-items: center;
          padding-top: var(--zimm-scale-200);
        }

        .icon-row a {
          display: inline-flex;
          align-items: center;
          justify-content: center;
        }

        /* ---- Logo ---- */
        .logo-area { display: flex; }

        /* ---- Bottom bar ---- */
        .bottom-bar {
          background-color: var(--zimm-color-bg-06);
          width: 100%;
        }

        .bottom-bar-inner {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: var(--zimm-scale-2xl) var(--zimm-scale-800);
          flex-wrap: wrap;
          gap: var(--zimm-scale-300);
        }

        .locale {
          display: inline-flex;
          align-items: center;
          gap: var(--zimm-scale-200);
          background: none;
          border: none;
          padding: 0;
          cursor: pointer;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-4xs);
          line-height: var(--zimm-font-lineheight-4xs);
          letter-spacing: var(--zimm-font-letterspacing-footer);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse);
          white-space: nowrap;
        }

        .locale:focus-visible {
          outline: 2px solid var(--zimm-color-text-inverse);
          outline-offset: 2px;
        }

        .legal {
          display: flex;
          align-items: center;
          gap: var(--zimm-scale-500);
          flex-wrap: wrap;
          justify-content: flex-end;
        }

        .legal span,
        .legal a {
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          font-size: var(--zimm-font-size-4xs);
          line-height: var(--zimm-font-lineheight-4xs);
          letter-spacing: var(--zimm-font-letterspacing-footer);
          text-transform: uppercase;
          color: var(--zimm-color-text-inverse-grey);
          text-decoration: none;
          white-space: nowrap;
        }

        /* Mobile: hide legal links, keep copyright only */
        .legal-link { display: none; }

        /* ---- Tablet: 768px+ ---- */
        @media (min-width: 768px) {
          .main {
            display: grid;
            grid-template-columns: 320px 1fr;
            grid-template-rows: auto auto;
            padding: var(--zimm-scale-1000) var(--zimm-scale-1000) 0;
            gap: 0 var(--zimm-scale-4xl);
          }

          .subscribe {
            grid-column: 1;
            grid-row: 1;
            padding-bottom: var(--zimm-scale-1000);
          }

          .logo-area {
            grid-column: 1;
            grid-row: 2;
            padding: 0 0 var(--zimm-scale-1000);
            align-items: flex-end;
          }

          .links {
            grid-column: 2;
            grid-row: 1 / span 2;
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            column-gap: var(--zimm-scale-1000);
            align-items: start;
            border-top: none;
            border-bottom: none;
            padding: 0 0 var(--zimm-scale-1000);
          }

          .link-group:nth-child(1),
          .link-group:nth-child(2),
          .link-group:nth-child(3) {
            grid-column: auto;
            grid-row: auto;
          }

          .legal-link { display: inline; }

          .bottom-bar-inner {
            padding: var(--zimm-scale-2xl) var(--zimm-scale-3xl);
          }
        }

        /* ---- Desktop: 1024px+ ---- */
        @media (min-width: 1024px) {
          .main {
            grid-template-columns: 320px 1fr 600px;
            grid-template-rows: auto auto;
            gap: 0 var(--zimm-scale-4xl);
            padding: var(--zimm-scale-4xl) var(--zimm-scale-3xl) 0;
          }

          .logo-area {
            grid-column: 1;
            grid-row: 2;
            padding: var(--zimm-scale-5xl) 0 var(--zimm-scale-4xl);
            align-items: flex-end;
          }

          .links {
            grid-column: 3;
            grid-row: 1 / span 2;
            grid-template-columns: repeat(3, 1fr);
            column-gap: var(--zimm-scale-1000);
          }

          .link-group:nth-child(1),
          .link-group:nth-child(2),
          .link-group:nth-child(3) {
            grid-column: auto;
            grid-row: auto;
          }
        }
      </style>

      <footer role="contentinfo">
        <div class="main">

          <div class="subscribe">
            <p class="label">Keep in Touch</p>
            <p class="body-text">Sign up to stay up to date on the latest news from Zimmermann.</p>
            <zimm-input-action label="Email" type="email" icon="chevron-right" button-label="Subscribe" inverse></zimm-input-action>
          </div>

          <div class="logo-area">
            <zimm-logo variant="inverse"></zimm-logo>
          </div>

          <div class="links">
            <div class="link-group">
              <p class="group-label">About</p>
              <ul>
                <li><a href="#">Our Story</a></li>
                <li><a href="#">Sustainability</a></li>
                <li><a href="#">Careers</a></li>
                <li><a href="#">Brand Protection</a></li>
                <li><a href="#">Acknowledgement of Country</a></li>
              </ul>
            </div>
            <div class="link-group">
              <p class="group-label">Contact</p>
              <ul>
                <li><a href="#">Boutique Locator</a></li>
                <li><a href="#">Book an Appointment</a></li>
                <li><a href="#">Connect with Us</a></li>
                <li class="icon-row">
                  <a href="tel:" aria-label="Call us"><zimm-icon type="phone" size="16" aria-hidden="true"></zimm-icon></a>
                  <a href="#" aria-label="WhatsApp"><zimm-icon type="whatsapp" size="16" aria-hidden="true"></zimm-icon></a>
                  <a href="mailto:" aria-label="Email us"><zimm-icon type="email" size="16" aria-hidden="true"></zimm-icon></a>
                </li>
              </ul>
            </div>
            <div class="link-group">
              <p class="group-label">Help</p>
              <ul>
                <li><a href="#">Orders &amp; Shipping</a></li>
                <li><a href="#">Return Policy</a></li>
                <li><a href="#">Submit a Return</a></li>
                <li><a href="#">FAQs</a></li>
                <li><a href="#">Size Guide</a></li>
              </ul>
            </div>
          </div>

        </div>

        <div class="bottom-bar">
          <div class="bottom-bar-inner">
            <button class="locale" type="button" aria-label="Change locale: United States (USD) / Eng">
              <span>United States (USD) / Eng</span>
              <zimm-icon type="chevron-right" size="12" aria-hidden="true"></zimm-icon>
            </button>
            <div class="legal">
              <span>Copyright &copy; 2026 Zimmermann</span>
              <a href="#" class="legal-link">Accessibility</a>
              <a href="#" class="legal-link">Privacy Policy</a>
              <a href="#" class="legal-link">Terms &amp; Conditions</a>
              <a href="#" class="legal-link">Modern Slavery</a>
              <a href="#" class="legal-link">Cookie Settings</a>
            </div>
          </div>
        </div>
      </footer>
    `;
  }
}

customElements.define('zimm-footer', ZimmFooter);

