class ZimmPageToolbar extends HTMLElement {
  static get observedAttributes() {
    return ['variant', 'heading', 'link-text', 'link-href'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    this._render();
  }

  _render() {
    const variant  = this.getAttribute('variant')   || 'breadcrumbs';
    const heading  = this.getAttribute('heading')   || '';
    const linkText = this.getAttribute('link-text') || '';
    const linkHref = this.getAttribute('link-href') || '#';

    const isHeadingRow = variant === 'recently-viewed' || variant === 'section-title';

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; background: var(--zimm-color-bg-07); }

        .toolbar {
          padding-left:   var(--zimm-scale-3xl);
          padding-right:  var(--zimm-scale-5xl);
          padding-bottom: var(--zimm-scale-2xl);
          padding-top:    var(--zimm-scale-m);
        }

        :host([variant="recently-viewed"]) .toolbar,
        :host([variant="section-title"]) .toolbar {
          padding-top: var(--zimm-scale-xs);
        }

        /* ---- Breadcrumbs ---- */
        .crumbs-row {
          font-family:    var(--zimm-font-family-body);
          font-weight:    var(--zimm-font-weight-medium);
          font-size:      var(--zimm-font-size-3xs);
          line-height:    normal;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          text-transform: uppercase;
          color:          var(--zimm-color-text-default);
          opacity:        0.8;
        }

        slot[name="crumbs"] { display: block; }

        slot[name="crumbs"]::slotted(a) {
          color:           var(--zimm-color-link-default);
          text-decoration: none;
          transition:      color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        slot[name="crumbs"]::slotted(a:hover) {
          color: var(--zimm-color-link-hover);
        }

        /* ---- Heading row ---- */
        .heading-row {
          display:         flex;
          align-items:     center;
          justify-content: space-between;
          width:           100%;
        }

        .heading {
          font-family:    var(--zimm-font-family-heading);
          font-weight:    var(--zimm-font-weight-medium);
          font-size:      var(--zimm-font-size-xs);
          line-height:    var(--zimm-font-lineheight-2xs);
          letter-spacing: var(--zimm-font-letterspacing-xs);
          text-transform: uppercase;
          color:          var(--zimm-color-text-default);
          margin:         0;
        }

        .heading-link {
          font-family:     var(--zimm-font-family-body);
          font-weight:     var(--zimm-font-weight-medium);
          font-size:       var(--zimm-font-size-2xs);
          line-height:     var(--zimm-font-lineheight-3xs);
          letter-spacing:  -0.14px;
          text-transform:  uppercase;
          text-decoration: underline;
          color:           var(--zimm-color-text-default);
          transition:      color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        .heading-link:hover { color: var(--zimm-color-text-secondary); }

        .heading-link:focus-visible {
          outline:        var(--zimm-border-width-default) solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }
      </style>

      <div class="toolbar">
        ${isHeadingRow ? `
          <div class="heading-row">
            <p class="heading">${heading}</p>
            ${linkText ? `<a class="heading-link" href="${linkHref}">${linkText}</a>` : ''}
          </div>
        ` : `
          <div class="crumbs-row">
            <slot name="crumbs"></slot>
          </div>
        `}
      </div>
    `;
  }
}

customElements.define('zimm-page-toolbar', ZimmPageToolbar);

