94	        slot[name="links"]::slotted(button:hover) {
95	          color: var(--zimm-color-text-secondary);
96	        }
97	
98	        slot[name="filters"]::slotted(*) {
99	          display:         inline-flex;
100	          align-items:     center;
101	          gap:             var(--zimm-scale-xs);
102	          font-family:     var(--zimm-font-family-body);
