108	          color:           var(--zimm-color-text-default);
109	          background:      none;
110	          border:          none;
111	          padding:         0;
112	          cursor:          pointer;
113	        }
114	
115	        /* ---- Right: filters + sort ---- */
116	        .right {
117	          display:     flex;
118	          align-items: center;
119	          gap:         0;
120	        }
121	
122	        .filters-link {
123	          font-family:     var(--zimm-font-family-body);
124	          font-weight:     var(--zimm-font-weight-medium);
125	          font-size:       var(--zimm-font-size-2xs);
126	          line-height:     var(--zimm-font-lineheight-3xs);
127	          letter-spacing:  -0.14px;
128	          text-transform:  uppercase;
