class ZimmToolbarCategory extends HTMLElement {
  static get observedAttributes() {
    return ['setting', 'sort-label'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this._render();
    this._bindSlotChange();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    this._render();
    this._bindSlotChange();
  }

  _bindSlotChange() {
    const linksSlot   = this.shadowRoot.querySelector('slot[name="links"]');
    const filtersSlot = this.shadowRoot.querySelector('slot[name="filters"]');
    if (linksSlot)   linksSlot.addEventListener('slotchange',   () => this._syncVisibility());
    if (filtersSlot) filtersSlot.addEventListener('slotchange', () => this._syncVisibility());
    this._syncVisibility();
  }

  _syncVisibility() {
    const filtersSlot = this.shadowRoot.querySelector('slot[name="filters"]');
    const linksSlot   = this.shadowRoot.querySelector('slot[name="links"]');
    const setting     = this.getAttribute('setting') || 'default';
    const isSelected  = setting === 'selected';

    if (linksSlot)   linksSlot.classList.toggle('hidden', isSelected);
    if (filtersSlot) filtersSlot.classList.toggle('hidden', !isSelected);
  }

  _render() {
    const setting   = this.getAttribute('setting')    || 'default';
    const sortLabel = this.getAttribute('sort-label') || 'Newest';
    const iconBase  = new URL('../icon/assets/', import.meta.url).href;

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; background: var(--zimm-color-bg-07); }

        .toolbar {
          display:         flex;
          align-items:     center;
          justify-content: space-between;
          padding-left:    var(--zimm-scale-3xl);
          padding-right:   var(--zimm-scale-5xl);
          padding-top:     var(--zimm-scale-xs);
          padding-bottom:  var(--zimm-scale-4xl);
        }

        /* ---- Left: category links or active filter tags ---- */
        .left {
          display:     flex;
          align-items: center;
          gap:         var(--zimm-scale-3xl);
        }

        slot[name="links"],
        slot[name="filters"] {
          display: contents;
        }

        slot[name="links"].hidden,
        slot[name="filters"].hidden {
          display: none;
        }

        slot[name="links"]::slotted(a),
        slot[name="links"]::slotted(button) {
          font-family:     var(--zimm-font-family-body);
          font-weight:     var(--zimm-font-weight-medium);
          font-size:       var(--zimm-font-size-2xs);
          line-height:     var(--zimm-font-lineheight-3xs);
          letter-spacing:  var(--zimm-font-letterspacing-sm);
          text-transform:  uppercase;
          color:           var(--zimm-color-text-default);
          text-decoration: none;
          background:      none;
          border:          none;
          padding:         0;
          cursor:          pointer;
          transition:      color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        slot[name="links"]::slotted(a:hover),
        slot[name="links"]::slotted(button:hover) {
          color: var(--zimm-color-text-secondary);
        }

        slot[name="filters"]::slotted(*) {
          display:         inline-flex;
          align-items:     center;
          gap:             var(--zimm-scale-xs);
          font-family:     var(--zimm-font-family-body);
          font-weight:     var(--zimm-font-weight-medium);
          font-size:       var(--zimm-font-size-2xs);
          line-height:     var(--zimm-font-lineheight-3xs);
          letter-spacing:  var(--zimm-font-letterspacing-sm);
          text-transform:  uppercase;
          color:           var(--zimm-color-text-default);
          background:      none;
          border:          none;
          padding:         0;
          cursor:          pointer;
        }

        /* ---- Right: filters + sort ---- */
        .right {
          display:     flex;
          align-items: center;
          gap:         0;
        }

        .filters-link {
          font-family:     var(--zimm-font-family-body);
          font-weight:     var(--zimm-font-weight-medium);
          font-size:       var(--zimm-font-size-2xs);
          line-height:     var(--zimm-font-lineheight-3xs);
          letter-spacing:  -0.14px;
          text-transform:  uppercase;
          text-decoration: underline;
          color:           var(--zimm-color-text-default);
          background:      none;
          border:          none;
          padding:         0;
          cursor:          pointer;
          transition:      color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        .filters-link:hover { color: var(--zimm-color-text-secondary); }
        .filters-link:focus-visible {
          outline:        var(--zimm-border-width-default) solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }

        .divider {
          width:      1px;
          height:     var(--zimm-scale-xl);
          background: var(--zimm-color-grey-900);
          margin:     0 var(--zimm-scale-s);
          flex-shrink: 0;
        }

        .sort-by {
          display:        flex;
          align-items:    center;
          gap:            var(--zimm-scale-xs);
          font-family:    var(--zimm-font-family-body);
          font-weight:    var(--zimm-font-weight-medium);
          font-size:      var(--zimm-font-size-2xs);
          line-height:    var(--zimm-font-lineheight-3xs);
          letter-spacing: -0.14px;
          text-transform: uppercase;
          color:          var(--zimm-color-text-default);
          background:     none;
          border:         none;
          padding:        0;
          cursor:         pointer;
        }

        .sort-label {
          text-decoration: underline;
        }

        .sort-by:hover .sort-label {
          color: var(--zimm-color-text-secondary);
        }

        .sort-by:focus-visible {
          outline:        var(--zimm-border-width-default) solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }

        .chevron {
          width:  var(--zimm-icon-size-md);
          height: var(--zimm-icon-size-md);
          display: block;
          flex-shrink: 0;
        }
      </style>

      <div class="toolbar">
        <div class="left">
          <slot name="links"></slot>
          <slot name="filters"></slot>
        </div>
        <div class="right">
          <button class="filters-link">Filters</button>
          <div class="divider" aria-hidden="true"></div>
          <button class="sort-by" aria-label="Sort by ${sortLabel}">
            <span>Sort by</span>
            <span class="sort-label">${sortLabel}</span>
            <img class="chevron" src="${iconBase}chevron-down.svg" alt="" aria-hidden="true">
          </button>
        </div>
      </div>
    `;
  }
}

customElements.define('zimm-toolbar-category', ZimmToolbarCategory);

