class ZimmHeroBlocks extends HTMLElement {
  static get observedAttributes() {
    return ['editorial-position', 'right-align'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this._render();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    this._render();
  }

  _render() {
    const rightAlign = this.getAttribute('right-align') || 'top';
    const justifyContent = rightAlign === 'bottom' ? 'flex-end' : 'flex-start';

    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: block;
        }

        .layout {
          display: flex;
          align-items: stretch;
          gap: 100px;
        }

        :host([editorial-position="right"]) .layout {
          flex-direction: row-reverse;
        }

        .editorial-cell {
          flex: 1;
          min-width: 0;
          height: 1200px;
          display: flex;
          flex-direction: column;
        }

        .editorial-cell ::slotted(*) {
          flex: 1;
          min-height: 0;
        }

        .right-cell {
          width: 280px;
          flex-shrink: 0;
          display: flex;
          flex-direction: column;
          justify-content: ${justifyContent};
        }

        @media (max-width: 1439px) {
          .layout {
            flex-direction: column !important;
            gap: var(--zimm-scale-3xl);
          }

          .right-cell {
            width: 100%;
            justify-content: flex-start;
          }
        }
      </style>

      <div class="layout">
        <div class="editorial-cell">
          <slot name="editorial"></slot>
        </div>
        <div class="right-cell">
          <slot name="right"></slot>
        </div>
      </div>
    `;
  }
}

customElements.define('zimm-hero-blocks', ZimmHeroBlocks);

