class ZimmProductShowcaseBlocks extends HTMLElement {
  static get observedAttributes() {
    return ['editorial-position', 'align-products'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this._render();
    this._bindSlotChange();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    this._render();
    this._bindSlotChange();
  }

  _bindSlotChange() {
    const productSlot = this.shadowRoot.querySelector('slot[name="product"]');
    const asideSlot   = this.shadowRoot.querySelector('slot[name="aside"]');
    productSlot.addEventListener('slotchange', () => this._syncAlignment());
    if (asideSlot) asideSlot.addEventListener('slotchange', () => this._syncAlignment());
    this._syncAlignment();
  }

  _syncAlignment() {
    const productSlot = this.shadowRoot.querySelector('slot[name="product"]');
    const asideSlot   = this.shadowRoot.querySelector('slot[name="aside"]');
    const cell        = this.shadowRoot.querySelector('.product-cell');
    if (!productSlot || !cell) return;

    const count    = productSlot.assignedElements().length;
    const twoCards = count <= 2;
    const hasAside = asideSlot && asideSlot.assignedElements().length > 0;

    // Aside only visible when 2 or fewer product cards are slotted
    if (asideSlot) asideSlot.classList.toggle('hidden', !twoCards);

    // 2 cards, no aside: bottom-align both cards
    cell.classList.toggle('auto-end', twoCards && !hasAside);

    // 2 cards with aside: space-between places aside at top, cards at bottom.
    // Placeholder (first child in shadow DOM) fills col2 row1 so cards fall to row 2.
    cell.classList.toggle('aside-two-cards', twoCards && hasAside);
  }

  _render() {
    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: block;
        }

        .layout {
          display: flex;
          align-items: stretch;
          gap: 100px;
        }

        :host([editorial-position="right"]) .layout {
          flex-direction: row-reverse;
        }

        .hero-cell {
          width: var(--hero-width, 664px);
          height: calc(2 * (var(--product-card-image-height, 438px) + 102px) + var(--product-row-gap, 50px));
          flex-shrink: 0;
          overflow: hidden;
          display: flex;
          flex-direction: column;
          justify-content: flex-start;
          --card-image-height: var(--hero-card-image-height, 1047px);
        }

        slot[name="hero"] {
          display: block;
        }

        slot[name="hero"]::slotted(*) {
          width: 100%;
        }

        .product-cell {
          flex-shrink: 0;
          display: grid;
          grid-template-columns: var(--product-card-width, 288px) var(--product-card-width, 288px);
          column-gap: 100px;
          row-gap: var(--product-row-gap, 50px);
          align-content: start;
          --card-image-height: var(--product-card-image-height, 438px);
        }

        /* 2 cards, no aside: both cards at bottom of container */
        .product-cell.auto-end,
        :host([align-products="end"]) .product-cell {
          align-content: end;
        }

        /* 2 cards with aside: aside pinned top, cards pushed to bottom.
           space-between distributes free space between row 1 (aside) and row 2 (cards). */
        .product-cell.aside-two-cards {
          align-content: space-between;
        }

        /* Placeholder fills col2 row1 when aside is active.
           Placed first in shadow DOM so grid auto-placement puts it immediately
           after the aside (order -1) at col2 row1, pushing cards to row 2. */
        .aside-placeholder {
          display: none;
          opacity: 0;
        }

        .product-cell.aside-two-cards .aside-placeholder {
          display: block;
        }

        slot[name="product"] {
          display: contents;
        }

        slot[name="aside"] {
          display: contents;
        }

        slot[name="aside"].hidden {
          display: none;
        }

        /* Aside always top-left of product grid.
           Hero left: aside is adjacent to hero.
           Hero right: aside is top-left of the full layout. */
        slot[name="aside"]::slotted(*) {
          order: -1;
        }

        /* Below 1440px: stack vertically, aside hidden.
           Switch to aspect-ratio so image height tracks actual card width,
           not viewport width. hero = 664:1047, product = 288:438. */
        @media (max-width: 1439px) {
          .layout {
            flex-direction: column !important;
            gap: 40px;
          }

          .hero-cell {
            width: 100%;
            height: auto;
            overflow: visible;
            justify-content: flex-start;
            --card-image-height: auto;
            --card-image-aspect-ratio: 664 / 1047;
          }

          .product-cell {
            width: 100%;
            grid-template-columns: 1fr 1fr;
            column-gap: var(--zimm-scale-3xl);
            align-content: start;
            --card-image-height: auto;
            --card-image-aspect-ratio: 288 / 438;
          }

          .product-cell.auto-end,
          .product-cell.aside-two-cards {
            align-content: start;
          }

          slot[name="aside"],
          slot[name="aside"].hidden {
            display: none;
          }

          .aside-placeholder {
            display: none !important;
          }
        }

        /* Mobile: same aspect-ratio approach, tighter column gap. */
        @media (max-width: 767px) {
          .product-cell {
            column-gap: var(--zimm-scale-3xl);
          }
        }
      </style>

      <div class="layout">
        <div class="hero-cell">
          <slot name="hero"></slot>
        </div>
        <div class="product-cell">
          <div class="aside-placeholder"></div>
          <slot name="product"></slot>
          <slot name="aside"></slot>
        </div>
      </div>
    `;
  }
}

customElements.define('zimm-product-showcase-blocks', ZimmProductShowcaseBlocks);

