class ZimmProductDetailGallery extends HTMLElement {
  static get observedAttributes() { return ['gallery-label']; }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(n, o, v) { if (o !== v) this._render(); }

  _render() {
    const commonCss    = new URL('../../common.css', import.meta.url).href;
    const galleryLabel = this.getAttribute('gallery-label') || 'Gallery';

    this.shadowRoot.innerHTML = `
      <link rel="stylesheet" href="${commonCss}">
      <style>
        :host { display: block; width: 100%; }

        .gallery {
          display: flex;
          flex-direction: column;
          position: relative;
        }

        /* Hero + video: proportional to gallery column width (980px : 1200px at 1440px) */
        .block-hero,
        .block-video {
          aspect-ratio: 49 / 60;
          overflow: hidden;
        }

        slot[name="image"],
        slot[name="video"] {
          display: block;
          height: 100%;
        }

        slot[name="image"]::slotted(*),
        slot[name="video"]::slotted(*) {
          display: block;
          width: 100%;
          height: 100%;
          object-fit: cover;
        }

        /* 2-column image grid */
        .grid {
          display: flex;
          flex-direction: column;
        }

        .grid-row {
          display: grid;
          grid-template-columns: 1fr 1fr;
        }

        /* Grid cells: proportional to cell width (490px : 560px at 1440px = 7:8) */
        .grid-cell {
          aspect-ratio: 7 / 8;
          overflow: hidden;
        }

        .grid-cell slot {
          display: block;
          height: 100%;
        }

        .grid-cell slot::slotted(*) {
          display: block;
          width: 100%;
          height: 100%;
          object-fit: cover;
        }

        /* Gallery button: floats over the component */
        .btn-gallery {
          position: absolute;
          bottom: var(--zimm-scale-2xl);
          right: var(--zimm-scale-2xl);
          font-family: var(--zimm-font-family-body);
          font-size: var(--zimm-font-size-2xs);
          font-weight: var(--zimm-font-weight-medium);
          text-transform: uppercase;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          background: var(--zimm-color-grey-white);
          color: var(--zimm-color-text-default);
          border: var(--zimm-border-width-default) solid var(--zimm-color-text-default);
          padding: var(--zimm-scale-xs) var(--zimm-scale-m);
          cursor: pointer;
          transition: background var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
        }

        .btn-gallery:hover { background: var(--zimm-color-bg-02); }

        .btn-gallery:focus-visible {
          outline: 2px solid var(--zimm-color-border-focus);
          outline-offset: 2px;
        }
      </style>

      <div class="gallery">

        <div class="block-hero">
          <slot name="image"></slot>
        </div>

        <div class="block-video">
          <slot name="video"></slot>
        </div>

        <div class="grid">
          <div class="grid-row">
            <div class="grid-cell"><slot name="grid-1"></slot></div>
            <div class="grid-cell"><slot name="grid-2"></slot></div>
          </div>
          <div class="grid-row">
            <div class="grid-cell"><slot name="grid-3"></slot></div>
            <div class="grid-cell"><slot name="grid-4"></slot></div>
          </div>
        </div>

        <button class="btn-gallery" aria-label="${galleryLabel}, view all images">${galleryLabel}</button>

      </div>
    `;
  }
}

customElements.define('zimm-product-detail-gallery', ZimmProductDetailGallery);

